    private MaterialSymbolsHelper() {
    }

    public static boolean hasSymbol(int resId) {
        return SYMBOLS.indexOfKey(resId) >= 0;
    }

    public static Drawable get(int resId) {
        String path = SYMBOLS.get(resId);
        if (path == null) {
            return null;
        }
        return new MaterialSymbolDrawable(path);
    }
